import{_ as i,o as e,c as l,ae as o}from"./chunks/framework.DJIAqD5B.js";const p=JSON.parse('{"title":"DirectXMod 开源项目贡献指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/directxmod.md","filePath":"guide/directxmod.md"}'),t={name:"guide/directxmod.md"};function r(s,a,d,n,h,c){return e(),l("div",null,[...a[0]||(a[0]=[o(`<h1 id="directxmod-开源项目贡献指南" tabindex="-1">DirectXMod 开源项目贡献指南 <a class="header-anchor" href="#directxmod-开源项目贡献指南" aria-label="Permalink to &quot;DirectXMod 开源项目贡献指南&quot;">​</a></h1><p>欢迎各位开发者参与本 Minecraft D3D12 渲染模组共建！ 无论你是提供技术方案、编写代码修复BUG、新增功能、优化性能、完善文档、测试排错，都可以参与项目。本文档说明当前待解决技术难题、参与流程、署名奖励机制、代码规范。</p><h4 id="你目前看到的已完成的是由爱睡觉的白洲梓测试模组-ai生成代码。使用了deepseek的api。你也可以使用ai生成贡献代码。但是记得声明使用了什么ai模型。" tabindex="-1">你目前看到的已完成的是由爱睡觉的白洲梓测试模组+AI生成代码。使用了Deepseek的API。你也可以使用AI生成贡献代码。但是记得声明使用了什么AI模型。 <a class="header-anchor" href="#你目前看到的已完成的是由爱睡觉的白洲梓测试模组-ai生成代码。使用了deepseek的api。你也可以使用ai生成贡献代码。但是记得声明使用了什么ai模型。" aria-label="Permalink to &quot;你目前看到的已完成的是由爱睡觉的白洲梓测试模组+AI生成代码。使用了Deepseek的API。你也可以使用AI生成贡献代码。但是记得声明使用了什么AI模型。&quot;">​</a></h4><h2 id="一、当前待攻坚核心难题-可自由认领" tabindex="-1">一、当前待攻坚核心难题（可自由认领） <a class="header-anchor" href="#一、当前待攻坚核心难题-可自由认领" aria-label="Permalink to &quot;一、当前待攻坚核心难题（可自由认领）&quot;">​</a></h2><h3 id="高优先级功能卡点" tabindex="-1">高优先级功能卡点 <a class="header-anchor" href="#高优先级功能卡点" aria-label="Permalink to &quot;高优先级功能卡点&quot;">​</a></h3><ol><li><p><strong>半透明物体渲染</strong> 卡点：玻璃、树叶、水等半透明物体渲染顺序错乱、Alpha混合色彩失真、深度排序性能开销大；D3D12混合状态无法对齐原版OpenGL视觉效果。 需求：实现相机距离动态深度排序、适配MC原生渲染逻辑、优化批量渲染性能。</p></li><li><p><strong>完整天空盒渲染管线</strong> 卡点：Java侧天空颜色、日月坐标、星空参数已全部提取，但C++ <code>nativeRenderSky</code> 未实现；昼夜渐变、星图批量渲染逻辑缺失。 需求：半球渐变着色、日月投影变换、星空顶点批量渲染、昼夜动画联动。</p></li><li><p><strong>粒子完整动画系统</strong> 卡点：仅基础粒子渲染框架，无图集帧动画、生命周期颜色渐变、深度校验逻辑，粒子会穿透实体。 需求：Shader帧插值、纹理分块采样、透明粒子深度剔除。</p></li><li><p><strong>实体骨骼蒙皮渲染</strong> 卡点：仅静态实体模型渲染，玩家、生物骨骼变换矩阵未提取，D3D12 GPU蒙皮管线未搭建。 需求：反射骨骼矩阵、常量缓冲区蒙皮计算、多实体批量渲染。</p></li></ol><h3 id="中长期开发任务" tabindex="-1">中长期开发任务 <a class="header-anchor" href="#中长期开发任务" aria-label="Permalink to &quot;中长期开发任务&quot;">​</a></h3><ul><li>多Pass分层渲染（分离3D场景、半透明物体、GUI界面）</li><li>统一Shader管理框架 + 后处理（抗锯齿、雾效、色彩校正）</li><li>JNI跨线程数据传输性能优化，减少帧内存拷贝</li><li>D3D12 SRV/RTV描述符堆动态扩容，解决大量纹理显存碎片</li><li>Sodium等主流光影模组兼容适配</li><li>窗口缩放、最小化、多显示器稳定性修复</li></ul><h2 id="二、三种参与贡献方式" tabindex="-1">二、三种参与贡献方式 <a class="header-anchor" href="#二、三种参与贡献方式" aria-label="Permalink to &quot;二、三种参与贡献方式&quot;">​</a></h2><h3 id="方式1-仅提供技术方案-无需编码" tabindex="-1">方式1：仅提供技术方案（无需编码） <a class="header-anchor" href="#方式1-仅提供技术方案-无需编码" aria-label="Permalink to &quot;方式1：仅提供技术方案（无需编码）&quot;">​</a></h3><ol><li>在GitHub Issues新建讨论，标题前缀 <code>[SOLUTION提案]</code></li><li>内容包含：目标问题、整体实现思路、D3D12/JNI技术细节、性能预估、潜在风险与规避方案</li><li>团队审核方案可行性，通过后两种选择： <ul><li>由你自行落地开发提交PR；</li><li>团队代为开发，源码、README均标注你的方案贡献。</li></ul></li></ol><h3 id="方式2-编写代码实现功能-修复bug-推荐" tabindex="-1">方式2：编写代码实现功能/修复BUG（推荐） <a class="header-anchor" href="#方式2-编写代码实现功能-修复bug-推荐" aria-label="Permalink to &quot;方式2：编写代码实现功能/修复BUG（推荐）&quot;">​</a></h3><ol><li>Fork 本仓库，新建分支，分支命名规范： <ul><li>修复BUG：<code>fix/xxx问题</code></li><li>新增功能：<code>feature/xxx功能</code></li></ul></li><li>完整自测：Windows平台、MC 26.1.2原版，覆盖窗口缩放、F6开关、F3调试等场景</li><li>Commit提交规范：<code>[模块] 实现/修复：功能描述</code> 示例：<code>[d3d12bridge] 实现半透明物体深度排序</code></li><li>提交Pull Request，关联对应Issue，附带测试截图/录屏</li><li>经过代码评审、版本测试后合并入库</li></ol><h3 id="方式3-文档、测试、辅助贡献" tabindex="-1">方式3：文档、测试、辅助贡献 <a class="header-anchor" href="#方式3-文档、测试、辅助贡献" aria-label="Permalink to &quot;方式3：文档、测试、辅助贡献&quot;">​</a></h3><ul><li>完善开发注释、补充开发文档、整理排错手册</li><li>提交BUG复现步骤、录制测试视频、整理场景测试用例</li></ul><h2 id="三、贡献署名永久激励规则-三重官方收录" tabindex="-1">三、贡献署名永久激励规则（三重官方收录） <a class="header-anchor" href="#三、贡献署名永久激励规则-三重官方收录" aria-label="Permalink to &quot;三、贡献署名永久激励规则（三重官方收录）&quot;">​</a></h2><p>只要你的方案被采纳、PR成功合并，将获得三层永久署名记录：</p><ol><li><strong>源码文件注释标注</strong> 在对应功能核心代码头部添加固定注释，记录你的GitHub昵称、修复版本、完成日期。 示例C++：</li></ol><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 半透明物体深度排序与Alpha混合实现</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 贡献开发者：GitHub@YourName | 版本：v0.4.0 | 完成日期：2026-XX-XX</span></span></code></pre></div><p>Java JNI代码同步添加对应注释。</p><ol start="2"><li><p><strong>项目README.md贡献者表格</strong> 所有有效贡献统一更新至README底部「贡献开发者」列表，永久留存。</p></li><li><p><strong>MC百科 Mod 官方词条开发团队</strong> 模组正式发布上架MC百科后，将你的GitHub昵称写入模组词条「开发团队」栏目，标注你负责攻克的渲染模块，永久对外展示。</p></li></ol><h3 id="贡献分级标准" tabindex="-1">贡献分级标准 <a class="header-anchor" href="#贡献分级标准" aria-label="Permalink to &quot;贡献分级标准&quot;">​</a></h3><ol><li>仅提供可行技术方案，未参与编码：源码注释鸣谢 + README名单记录</li><li>核心功能完整实现、重大渲染BUG修复（半透明/天空盒/粒子/骨骼蒙皮等）：三重全署名（源码+README+MC百科）</li><li>小BUG修复、文档完善、兼容性适配：仅README贡献名单收录</li></ol><h2 id="四、统一开发规范" tabindex="-1">四、统一开发规范 <a class="header-anchor" href="#四、统一开发规范" aria-label="Permalink to &quot;四、统一开发规范&quot;">​</a></h2><ol><li>C++ D3D12代码遵循微软DirectX12标准编码风格；Java Fabric Mixin遵循MC模组通用规范</li><li>所有新增JNI接口必须增加D3D核心对象空指针校验，杜绝0xc010崩溃!尤其注意！！！，爱睡觉的白洲梓踩了很多次坑(C++端)</li><li>新增顶点、矩阵、纹理逻辑兼容现有顶点自动检测框架，不破坏现有渲染管线</li><li>提交PR必须附带完整测试记录，覆盖窗口缩放、切换渲染开关、多实体场景等用例</li></ol><h2 id="五、沟通渠道" tabindex="-1">五、沟通渠道 <a class="header-anchor" href="#五、沟通渠道" aria-label="Permalink to &quot;五、沟通渠道&quot;">​</a></h2><p>所有技术方案讨论、BUG反馈、开发疑问统一在仓库 GitHub Issues 提交，维护者会定期回复评审。</p><h2 id="开源协议" tabindex="-1">开源协议 <a class="header-anchor" href="#开源协议" aria-label="Permalink to &quot;开源协议&quot;">​</a></h2><p>本项目使用 MIT 开源协议，所有提交的代码、文档均遵循 MIT 协议对外开放。</p>`,29)])])}const b=i(t,[["render",r]]);export{p as __pageData,b as default};
